#include <emscripten/bind.h>
#include <libqalculate/qalculate.h>
#include <fstream>
using namespace emscripten;
EvaluationOptions evalops;
PrintOptions printops;
#include "settings.h"
val plotData=val::null();
std::string qalc_gnuplot_data_dir(){return "/tmp";}
bool qalc_invoke_gnuplot(std::vector<std::pair<std::string,std::string>> files,std::string commands,std::string extra,bool persist){plotData=val::object();val data=val::object();for(auto &f:files)data.set(f.first,f.second);plotData.set("data",data);plotData.set("commands",commands);return true;}
val item(ExpressionItem *p){val v=val::object(),a=val::array();v.set("name",p->referenceName());v.set("title",p->title());v.set("description",p->description());v.set("category",p->category());v.set("active",p->isActive());v.set("local",p->isLocal());v.set("hidden",p->isHidden());for(size_t i=1;i<=p->countNames();i++)a.call<void>("push",p->getName(i).name);v.set("aliases",a);return v;}
val catalog(){val out=val::object(),fs=val::array(),us=val::array(),vs=val::array(),ps=val::array();for(auto f:CALCULATOR->functions){val v=item(f),args=val::array();v.set("example",f->example());if(auto uf=dynamic_cast<UserFunction*>(f))v.set("formula",uf->formula());v.set("minArgs",f->minargs());v.set("maxArgs",f->maxargs());v.set("condition",f->printCondition());for(size_t i=1;i<=f->lastArgumentDefinitionIndex();i++){auto a=f->getArgumentDefinition(i);val av=val::object();av.set("index",i);av.set("name",a?a->name():"");av.set("description",a?a->printlong():"");av.set("default",f->getDefaultValue(i));args.call<void>("push",av);}v.set("arguments",args);fs.call<void>("push",v);}for(auto u:CALCULATOR->units){val v=item(u);v.set("currency",u->isCurrency());if(auto au=dynamic_cast<AliasUnit*>(u)){v.set("formula",au->expression());v.set("inverse",au->inverseExpression());v.set("baseUnit",au->baseUnit()->referenceName());}us.call<void>("push",v);}for(auto v:CALCULATOR->variables){auto info=item(v);if(v->isKnown())info.set("formula",static_cast<KnownVariable*>(v)->expression());vs.call<void>("push",info);}for(auto p:CALCULATOR->prefixes){val v=val::object();v.set("name",p->referenceName());v.set("title",p->longName());v.set("value",p->value().print());ps.call<void>("push",v);}out.set("functions",fs);out.set("units",us);out.set("variables",vs);out.set("prefixes",ps);out.set("version","5.13.0");return out;}
val calculate(std::string text){CALCULATOR->clearMessages();plotData=val::null();std::string parsed;bool comparison=false;auto result=CALCULATOR->calculateAndPrint(CALCULATOR->unlocalizeExpression(text,evalops.parse_options),0,evalops,printops,AUTOMATIC_FRACTION_AUTO,AUTOMATIC_APPROXIMATION_AUTO,&parsed,-1,&comparison);val out=val::object(),messages=val::array();out.set("input",parsed);out.set("output",result);while(auto m=CALCULATOR->message()){val v=val::object();v.set("type",int(m->type()));v.set("text",m->message());messages.call<void>("push",v);CALCULATOR->nextMessage();}out.set("messages",messages);out.set("plot",plotData);return out;}
int loadDefinitions(std::string xml){std::ofstream f("/tmp/import.xml");f<<xml;f.close();return CALCULATOR->loadDefinitions("/tmp/import.xml",true,true);}
val exportDefinitions(){val out=val::object();out.set("temporary",CALCULATOR->saveTemporaryDefinitions());CALCULATOR->saveVariables("/tmp/variables.xml");CALCULATOR->saveFunctions("/tmp/functions.xml");CALCULATOR->saveUnits("/tmp/units.xml");CALCULATOR->saveDataSets("/tmp/datasets.xml");for(auto name:{"variables","functions","units","datasets"}){std::ifstream f(std::string("/tmp/")+name+".xml");std::string text((std::istreambuf_iterator<char>(f)),std::istreambuf_iterator<char>());out.set(name,text);}return out;}
val datasets(){val out=val::array();for(size_t i=1;;i++){DataSet *d=CALCULATOR->getDataSet(i);if(!d)break;d->loadObjects();val v=item(d),props=val::array(),rows=val::array();std::vector<DataProperty*> pp;DataPropertyIter pi;for(auto p=d->getFirstProperty(&pi);p;p=d->getNextProperty(&pi)){pp.push_back(p);val pv=val::object();pv.set("name",p->getReferenceName());pv.set("title",p->title());pv.set("description",p->description());pv.set("unit",p->getUnitString());pv.set("key",p->isKey());props.call<void>("push",pv);}DataObjectIter oi;for(auto o=d->getFirstObject(&oi);o;o=d->getNextObject(&oi)){val row=val::object();for(auto p:pp)row.set(p->getReferenceName(),o->getPropertyInputString(p));rows.call<void>("push",row);}v.set("properties",props);v.set("rows",rows);v.set("copyright",d->copyright());out.call<void>("push",v);}return out;}
int main(){new Calculator();CALCULATOR->loadGlobalDefinitions();printops.use_unicode_signs=true;printops.interval_display=INTERVAL_DISPLAY_SIGNIFICANT_DIGITS;printops.base_display=BASE_DISPLAY_NORMAL;printops.indicate_infinite_series=true;evalops.parse_options.angle_unit=ANGLE_UNIT_RADIANS;return 0;}
EMSCRIPTEN_BINDINGS(Qalculate){function("catalog",&catalog);function("options",&options);function("datasets",&datasets);function("calculate",&calculate);function("setOption",&set_option);function("loadDefinitions",&loadDefinitions);function("exportDefinitions",&exportDefinitions);}
